 }
+
+function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
+  const limit = readLimit(message.limit);
+  if (!limit.ok) {
+    return {valid: false, error: limit.error};
+  }
+
+  const before = readBefore(message.before);
+  if (!before.ok) {
+    return {valid: false, error: before.error};
+  }
+
+  const frame: ListSessionsMessage = {type: 'list_sessions'};
+  if (limit.value !== undefined) {
+    frame.limit = limit.value;
+  }
+  if (before.value !== undefined) {
+    frame.before = before.value;
+  }
+
+  return {valid: true, data: frame};
+}
+
+function readLimit(raw: unknown): ParsedField<number | undefined> {
+  if (raw === undefined) {
+    return {ok: true, value: undefined};
+  }
+  if (!isValidLimit(raw)) {
+    return {ok: false, error: 'list_sessions limit must be a non-negative integer'};
+  }
+  return {ok: true, value: raw};
+}
+
+function isValidLimit(raw: unknown): raw is number {
+  if (typeof raw !== 'number') return false;
+  return Number.isInteger(raw) && raw >= 0;
+}
+
+function readBefore(raw: unknown): ParsedField<CursorPayload | undefined> {
+  if (raw === undefined) {
+    return {ok: true, value: undefined};
+  }
+  if (!isPlainObject(raw)) {
+    return {ok: false, error: 'list_sessions before must be an object'};
+  }
+  if (!isValidSessionId(raw.sessionId)) {
+    return {ok: false, error: 'list_sessions before.sessionId must be 1-128 characters'};
+  }
+  if (!isValidTimestamp(raw.updatedAt)) {
+    return {ok: false, error: 'list_sessions before.updatedAt must be a valid timestamp'};
+  }
+  return {
+    ok: true,
+    value: {
+      updatedAt: raw.updatedAt,
+      sessionId: raw.sessionId,
+    },
+  };
+}
+
+function isPlainObject(raw: unknown): raw is Record<string, unknown> {
+  if (typeof raw !== 'object' || raw === null) return false;
+  return !Array.isArray(raw);
+}
+
+function isValidSessionId(raw: unknown): raw is string {
+  if (typeof raw !== 'string') return false;
+  return raw.length >= 1 && raw.length <= MAX_SESSION_ID_LENGTH;
+}
+
+function isValidTimestamp(raw: unknown): raw is string | number {
+  if (typeof raw === 'number') {
+    return Number.isFinite(raw) && Number.isFinite(new Date(raw).getTime());
+  }
+  if (typeof raw === 'string') {
+    return raw.trim().length > 0 && Number.isFinite(new Date(raw).getTime());
+  }
+  return false;
+}
