// What the client saw of the turn: whether the answer streamed, the last frame, and any error frames.
function outcomeOf(frames: string[]): {answered: boolean; last: string | undefined; errors: string[]} {
  return {
    answered: frames.some(frame => frame.startsWith('delta') && frame.endsWith(JSON.stringify('all done'))),
    last: frames.at(-1),
    errors: frames.filter(frame => frame.startsWith('error')),
  };
}

describe('listing conversations for the session owner', () => {
  const logged = captureErrors();

  it('answers list_sessions off the turn lock with ISO dates, an empty list without listFor, and SERVER_ERROR when listFor fails', async () => {
    const gate = deferred();
    const orchestrator = {
      async *processMessageStream(): AsyncGenerator<MessageChunk> {
        yield text('working');
        await gate.until;
        yield STOP;
      },
    } as unknown as ChatOrchestrator;
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const cursor: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's9'};
    const listingStore: SessionStore = {
      ...fiveMemberStore,
      listFor: (userId, options) => {
        seen.push({userId, options});
        return [
          {
            sessionId: 's2',
            createdAt: new Date('2026-01-01T00:00:00.000Z'),
            updatedAt: new Date('2026-01-01T00:02:00.000Z'),
            entryCount: 3,
          },
        ];
      },
    };
    const sent: OutgoingMessage[] = [];
    const ws = {
      readyState: WebSocket.OPEN,
      send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage),
    } as unknown as WebSocket;

    const handle = createMessageHandler(orchestrator, listingStore);
    const turn = handle(ws, session, userMessage('hello'));
    await afterPendingWork();
    await handle(ws, session, {type: 'list_sessions', limit: 5, before: cursor, userId: 'intruder'});
    const whileStreaming = sent.filter(frame => frame.type === 'session_list' || frame.type === 'stream_end');
    gate.release();
    await turn;

    const omittedFrames = await sendListOnce(createMessageHandler(orchestrator), session);
    const bareFrames = await sendListOnce(createMessageHandler(orchestrator, fiveMemberStore), session);
    const failedErrorFrames = await sendListOnce(
      createMessageHandler(orchestrator, {
        ...fiveMemberStore,
        listFor: () => Promise.reject(new Error('store offline')),
      }),
      session
    );
    const failedTextFrames = await sendListOnce(
      createMessageHandler(orchestrator, {
        ...fiveMemberStore,
        listFor: () => Promise.reject('raw rejection'),
      }),
      session
    );

    expect({
      seen,
      whileStreaming,
      omittedFrames,
      bareFrames,
      failedCodes: [...failedErrorFrames, ...failedTextFrames].map(frame =>
        frame.type === 'error' ? frame.code : frame.type
      ),
      logged: logged.map(({category, userId, error}) => ({category, userId, error})),
    }).toEqual({
      seen: [{userId: 'u1', options: {limit: 5, before: cursor}}],
      whileStreaming: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 's2',
              createdAt: '2026-01-01T00:00:00.000Z',
              updatedAt: '2026-01-01T00:02:00.000Z',
              entryCount: 3,
            },
          ],
        },
      ],
      omittedFrames: [{type: 'session_list', sessions: []}],
      bareFrames: [{type: 'session_list', sessions: []}],
      failedCodes: ['SERVER_ERROR', 'SERVER_ERROR'],
      logged: [
        {category: 'ws', userId: 'u1', error: 'store offline'},
        {category: 'ws', userId: 'u1', error: 'raw rejection'},
      ],
    });
  });
});

async function sendListOnce(
  handle: ReturnType<typeof createMessageHandler>,
  session: ChatSession
): Promise<OutgoingMessage[]> {
  const sent: OutgoingMessage[] = [];
  const ws = {
    readyState: WebSocket.OPEN,
    send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage),
  } as unknown as WebSocket;
  await handle(ws, session, {type: 'list_sessions'});
  return sent;
}

